//! Byte-level character classification, mirroring `<cctype>` under the "C" locale.
//!
//! The C++ original walks `std::string` one `char` at a time, so every transformation
//! is really a byte transformation: bytes >= 0x80 are never classified as letters and
//! therefore pass through untouched. Working on `&[u8]` here keeps that behaviour
//! exact for multi-byte UTF-8 input instead of accidentally case-folding it.

pub fn is_upper(b: u8) -> bool {
    b.is_ascii_uppercase()
}

pub fn is_alnum(b: u8) -> bool {
    b.is_ascii_alphanumeric()
}

pub fn to_upper(b: u8) -> u8 {
    b.to_ascii_uppercase()
}

pub fn to_lower(b: u8) -> u8 {
    b.to_ascii_lowercase()
}

/// True for the vowel set used by the `([^aeiouy]|qu)ies$` singular rule.
pub fn is_vowel_or_y(b: u8) -> bool {
    matches!(b, b'a' | b'e' | b'i' | b'o' | b'u' | b'y')
}

/// Turns a transformed byte buffer back into a `String`.
///
/// Every transformation in this crate either copies a byte verbatim, inserts an ASCII
/// byte, or drops a run of non-ASCII bytes in full, so a valid UTF-8 input always
/// yields a valid UTF-8 result. The lossy branch only exists so a surprising input
/// degrades instead of panicking.
pub fn finish(bytes: Vec<u8>) -> String {
    String::from_utf8(bytes)
        .unwrap_or_else(|e| String::from_utf8_lossy(e.as_bytes()).into_owned())
}

