//! Inflection rule tables.
//!
//! The rule set is a *pruned* version of the classic Ruby/Rails inflector: a number of
//! its exception rules are demonstrably absent from the C++ library this port
//! reproduces (`(shoe)s`, `(tive)s`, `(hive)s`, `(m)ovies`, `(s)eries`, `(bus)(es)?`,
//! `(alias|status)`, `(octop|vir)`, `(cris|test)`, `(ss)$` and `^(ox)en` all fail to
//! fire), and there is no plural rule table at all. The comments below record the
//! pattern each surviving rule stands in for.

use super::ascii::is_vowel_or_y;

/// Words that are their own plural *and* their own singular. Matched case-sensitively
/// against the whole string, so `Sheep` pluralizes to `Sheeps`.
pub const UNCOUNTABLE: &[&str] = &[
    "equipment",
    "information",
    "rice",
    "money",
    "species",
    "series",
    "fish",
    "sheep",
    "jeans",
    "police",
];

pub fn is_uncountable(word: &str) -> bool {
    UNCOUNTABLE.contains(&word)
}

/// A singular rule: `Some(replacement)` when the pattern matches the tail of `s`.
type SingularRule = fn(&[u8]) -> Option<Vec<u8>>;

/// Singular rules in match order; the first one that matches wins.
pub const SINGULAR_RULES: &[SingularRule] = &[
    quiz_zes,
    matr_ices,
    vert_ind_ices,
    a_x_i_e_s,
    o_es,
    x_ch_ss_sh_es,
    ies_to_y,
    ves_to_fe,
    sis_ses,
    news,
    trailing_s,
];

/// Applies the first matching singular rule, leaving `s` alone if none match.
pub fn singularize_bytes(s: &[u8]) -> Vec<u8> {
    SINGULAR_RULES
        .iter()
        .find_map(|rule| rule(s))
        .unwrap_or_else(|| s.to_vec())
}

/// Drops `cut` trailing bytes and appends `repl`.
fn replace_tail(s: &[u8], cut: usize, repl: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(s.len() - cut + repl.len());
    out.extend_from_slice(&s[..s.len() - cut]);
    out.extend_from_slice(repl);
    out
}

/// `(quiz)zes$` -> `\1`
fn quiz_zes(s: &[u8]) -> Option<Vec<u8>> {
    s.ends_with(b"quizzes").then(|| replace_tail(s, 3, b""))
}

/// `(matr)ices$` -> `\1ix`
fn matr_ices(s: &[u8]) -> Option<Vec<u8>> {
    s.ends_with(b"matrices").then(|| replace_tail(s, 4, b"ix"))
}

/// `(vert|ind)ices$` -> `\1ex`
fn vert_ind_ices(s: &[u8]) -> Option<Vec<u8>> {
    if s.ends_with(b"vertices") || s.ends_with(b"indices") {
        Some(replace_tail(s, 4, b"ex"))
    } else {
        None
    }
}

/// `^(a)x[ie]s$` -> `\1xis` -- anchored at both ends, so only `axes`/`axis` match.
fn a_x_i_e_s(s: &[u8]) -> Option<Vec<u8>> {
    (s == b"axes" || s == b"axis").then(|| b"axis".to_vec())
}

/// `(o)es$` -> `\1`
fn o_es(s: &[u8]) -> Option<Vec<u8>> {
    s.ends_with(b"oes").then(|| replace_tail(s, 2, b""))
}

/// `(x|ch|ss|sh)es$` -> `\1`
fn x_ch_ss_sh_es(s: &[u8]) -> Option<Vec<u8>> {
    let matched = s.ends_with(b"xes")
        || s.ends_with(b"ches")
        || s.ends_with(b"sses")
        || s.ends_with(b"shes");
    matched.then(|| replace_tail(s, 2, b""))
}

/// `([^aeiouy]|qu)ies$` -> `\1y`
fn ies_to_y(s: &[u8]) -> Option<Vec<u8>> {
    if !s.ends_with(b"ies") || s.len() < 4 {
        return None;
    }
    let stem = &s[..s.len() - 3];
    let last = *stem.last().unwrap();
    // Either the character before `ies` is not a vowel, or it is the `u` of a `qu`.
    let matched = !is_vowel_or_y(last) || stem.ends_with(b"qu");
    matched.then(|| replace_tail(s, 3, b"y"))
}

/// `([^f])ves$` -> `\1fe`
fn ves_to_fe(s: &[u8]) -> Option<Vec<u8>> {
    if !s.ends_with(b"ves") || s.len() < 4 {
        return None;
    }
    (s[s.len() - 4] != b'f').then(|| replace_tail(s, 3, b"fe"))
}

/// `((a)naly|(b)a|(d)iagno|(p)arenthe|(p)rogno|(s)ynop|(t)he)(sis|ses)$`
///
/// The C++ library expands this to `\1\2sis` rather than `\1sis`. Group 2 only
/// participates in the `analy` branch, so every stem round-trips correctly except
/// `analyses`, which picks up a stray `a` and becomes `analyasis`. That quirk is
/// observable in the reference binary, so it is reproduced verbatim.
fn sis_ses(s: &[u8]) -> Option<Vec<u8>> {
    /// Alternatives as (group 1, group 2), longest first: the regex engine takes the
    /// leftmost start position, which among stems ending at the same offset is the
    /// longest one.
    const STEMS: &[(&[u8], &[u8])] = &[
        (b"parenthe", b""),
        (b"diagno", b""),
        (b"progno", b""),
        (b"analy", b"a"),
        (b"synop", b""),
        (b"the", b""),
        (b"ba", b""),
    ];

    if !s.ends_with(b"sis") && !s.ends_with(b"ses") {
        return None;
    }
    let stem = &s[..s.len() - 3];
    let (g1, g2) = STEMS.iter().find(|(g1, _)| stem.ends_with(g1))?;

    let mut out = Vec::with_capacity(stem.len() + g2.len() + 3);
    out.extend_from_slice(&stem[..stem.len() - g1.len()]);
    out.extend_from_slice(g1);
    out.extend_from_slice(g2);
    out.extend_from_slice(b"sis");
    Some(out)
}

/// `(n)ews$` -> `\1ews` -- a no-op replacement that shields `news` from `s$`.
fn news(s: &[u8]) -> Option<Vec<u8>> {
    s.ends_with(b"news").then(|| s.to_vec())
}

/// `s$` -> `` -- the catch-all.
fn trailing_s(s: &[u8]) -> Option<Vec<u8>> {
    s.ends_with(b"s").then(|| replace_tail(s, 1, b""))
}

