//! The `Inflector` façade: the thirteen string transformations exposed by the C++
//! `inflection::Inflector`, reproduced byte-for-byte.

use super::ascii::{finish, is_alnum, is_upper, to_lower, to_upper};
use super::rules::{is_uncountable, singularize_bytes};

pub struct Inflector;

impl Inflector {
    /// Present for API parity with the C++ original, which uses it to populate its
    /// static rule tables. The tables here are `const`, so there is nothing to do.
    pub fn initialize() {}

    /// Appends `s`, unless the word is empty or uncountable. There is no plural rule
    /// table: `box` becomes `boxs` and `city` becomes `citys`.
    pub fn pluralize(word: &str) -> String {
        if word.is_empty() || is_uncountable(word) {
            return word.to_string();
        }
        format!("{}s", word)
    }

    /// Strips the plural suffix using the first matching rule in
    /// [`super::rules::SINGULAR_RULES`].
    pub fn singularize(word: &str) -> String {
        if word.is_empty() || is_uncountable(word) {
            return word.to_string();
        }
        finish(singularize_bytes(word.as_bytes()))
    }

    /// `foo_bar` -> `fooBar`. Underscores are separators: each one is dropped and the
    /// following byte is upper-cased.
    pub fn camelize(word: &str) -> String {
        Self::camelize_with(word, false)
    }

    /// [`Inflector::camelize`] with control over the first character, as used by
    /// [`Inflector::classify`].
    pub fn camelize_with(word: &str, upper_first: bool) -> String {
        let mut out = Vec::with_capacity(word.len());
        let mut capitalize = upper_first;
        for &b in word.as_bytes() {
            if b == b'_' {
                capitalize = true;
                continue;
            }
            out.push(if capitalize { to_upper(b) } else { b });
            capitalize = false;
        }
        finish(out)
    }

    /// `FooBar` -> `foo_bar`. Every upper-case byte past the first is prefixed with an
    /// underscore, so runs of capitals split apart: `FISH` -> `f_i_s_h`.
    pub fn underscore(word: &str) -> String {
        let mut out = Vec::with_capacity(word.len());
        for &b in word.as_bytes() {
            if is_upper(b) {
                if !out.is_empty() {
                    out.push(b'_');
                }
                out.push(to_lower(b));
            } else {
                out.push(b);
            }
        }
        finish(out)
    }

    /// `foo_bar` -> `FooBar`. Note that it camelizes the string as given; it does not
    /// run [`Inflector::underscore`] first, so `A B_table` -> `A BTable`.
    pub fn classify(word: &str) -> String {
        Self::camelize_with(&Self::singularize(word), true)
    }

    /// `FooBar` -> `foo_bars`.
    pub fn tableize(word: &str) -> String {
        Self::pluralize(&Self::underscore(word))
    }

    /// `foo_bar` -> `Foo bar`. Underscores become spaces and the first byte is
    /// upper-cased; the rest of the string keeps its original case.
    pub fn humanize(word: &str) -> String {
        let mut out: Vec<u8> = word
            .as_bytes()
            .iter()
            .map(|&b| if b == b'_' { b' ' } else { b })
            .collect();
        if let Some(first) = out.first_mut() {
            *first = to_upper(*first);
        }
        finish(out)
    }

    /// `hello world` -> `Hello World`. Only the space character starts a new word, so
    /// `hello_world` -> `Hello_world`, and the tail of each word is lower-cased.
    pub fn titleize(word: &str) -> String {
        let mut out = Vec::with_capacity(word.len());
        let mut capitalize = true;
        for &b in word.as_bytes() {
            if b == b' ' {
                out.push(b' ');
                capitalize = true;
            } else {
                out.push(if capitalize { to_upper(b) } else { to_lower(b) });
                capitalize = false;
            }
        }
        finish(out)
    }

    /// `foo_bar` -> `foo-bar`.
    pub fn dasherize(word: &str) -> String {
        let out = word
            .as_bytes()
            .iter()
            .map(|&b| if b == b'_' { b'-' } else { b })
            .collect();
        finish(out)
    }

    /// `The Foo Test` -> `the-foo-test`. Alphanumerics are lower-cased, each space
    /// becomes a dash, and everything else is discarded. Runs of dashes are *not*
    /// collapsed and leading/trailing dashes are *not* trimmed.
    pub fn parameterize(word: &str) -> String {
        let mut out = Vec::with_capacity(word.len());
        for &b in word.as_bytes() {
            if is_alnum(b) {
                out.push(to_lower(b));
            } else if b == b' ' {
                out.push(b'-');
            }
        }
        finish(out)
    }

    pub fn upcase(word: &str) -> String {
        finish(word.as_bytes().iter().map(|&b| to_upper(b)).collect())
    }

    pub fn downcase(word: &str) -> String {
        finish(word.as_bytes().iter().map(|&b| to_lower(b)).collect())
    }

    /// Upper-cases the first byte and lower-cases the rest: `FISH` -> `Fish`.
    pub fn capitalize(word: &str) -> String {
        let mut out: Vec<u8> = word.as_bytes().iter().map(|&b| to_lower(b)).collect();
        if let Some(first) = out.first_mut() {
            *first = to_upper(*first);
        }
        finish(out)
    }
}

